Here's a simple web-based game where the player needs to catch fruits with their mouth. I'll use HTML, CSS, and JavaScript to create an interactive game. Save this code in an HTML file and open it in a web browser:

```html
<!DOCTYPE html>
<html>
<head>
    <title>Fruit Catcher</title>
    <style>
        body {
            display: flex;
            flex-direction: column;
            align-items: center;
            background-color: #f0f0f0;
            font-family: Arial, sans-serif;
        }

        #gameCanvas {
            border: 2px solid #333;
            margin: 20px;
        }

        #score {
            font-size: 24px;
            margin-bottom: 20px;
        }

        #startButton {
            padding: 10px 20px;
            font-size: 18px;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
        }

        #restartButton {
            padding: 10px 20px;
            font-size: 18px;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            display: none;
        }
    </style>
</head>
<body>
    <div id="score">Score: 0</div>
    <canvas id="gameCanvas" width="400" height="600"></canvas>
    <button id="startButton">Start Game</button>
    <button id="restartButton">Restart</button>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const startButton = document.getElementById('startButton');
        const restartButton = document.getElementById('restartButton');
        let isGameRunning = false;
        let score = 0;

        // Player object
        const player = {
            x: 50,
            y: 50,
            mouthOpen: 0,
            mouthSpeed: 0.15
        };

        // Fruits array
        let fruits = [];
        const fruitTypes = ['apple', 'banana', 'orange', 'grape'];
        const fruitSpeeds = [3, 4, 2, 5];
        const fruitPositions = ['left', 'right', 'top', 'bottom'];

        // Game variables
        let gameLoop;
        let lastTime;
        const gameSpeed = 60;

        function drawPlayer() {
            // Player's head
            ctx.beginPath();
            ctx.arc(player.x, player.y, 20, 0, Math.PI * 2);
            ctx.fillStyle = '#333';
            ctx.fill();

            // Player's mouth
            ctx.beginPath();
            ctx.arc(player.x, player.y, player.mouthOpen, 0.2 * Math.PI, 1.8 * Math.PI);
            ctx.strokeStyle = '#333';
            ctx.stroke();
        }

        function drawFruit(fruit) {
            const x = fruit.x;
            const y = fruit.y;
            const radius = 20;

            // Draw fruit shape based on type
            switch(fruit.type) {
                case 'apple':
                    ctx.beginPath();
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                    ctx.fillStyle = '#FFD700';
                    ctx.fill();
                    break;
                case 'banana':
                    ctx.beginPath();
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                    ctx.fillStyle = '#FFA500';
                    ctx.fill();
                    break;
                case 'orange':
                    ctx.beginPath();
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                    ctx.fillStyle = '#FFA500';
                    ctx.fill();
                    break;
                case 'grape':
                    ctx.beginPath();
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                    ctx.fillStyle = '#800080';
                    ctx.fill();
                    break;
            }
        }

        function updatePlayer() {
            const currentTime = Date.now();
            const deltaTime = currentTime - lastTime;
            lastTime = currentTime;

            // Move player mouth
            player.mouthOpen += deltaTime * player.mouthSpeed;
            if (player.mouthOpen > 0) {
                player.mouthOpen -= 0.15;
            } else {
                player.mouthOpen = 0;
            }

            // Move fruits
            fruits = fruits.filter(fruit => {
                fruit.x += fruit.speed * Math.cos(fruit.angle) * deltaTime / 1000;
                fruit.y += fruit.speed * Math.sin(fruit.angle) * deltaTime / 1000;

                // Check if fruit is still on screen
                if (fruit.x < 0 || fruit.x > canvas.width || fruit.y < 0 || fruit.y > canvas.height) {
                    return false;
                }

                return true;
            });

            // Check collisions
            fruits = fruits.filter(fruit => {
                const dx = fruit.x - player.x;
                const dy = fruit.y - player.y;
                const distance = Math.sqrt(dx * dx + dy * dy);

                if (distance > player.mouthOpen) {
                    return false;
                }

                score += 10;
                document.getElementById('score').textContent = `Score: ${score}`;
                return false;
            });

            // Spawn new fruits
            if (fruits.length === 0 || (Math.random() < 0.02 * (1 + score / 100))) {
                const type = fruitTypes[Math.floor(Math.random() * fruitTypes.length)];
                const speed = fruitSpeeds[Math.floor(Math.random() * fruitSpeeds.length)];
                const position = fruitPositions[Math.floor(Math.random() * fruitPositions.length)];
                fruits.push({
                    type: type,
                    x: canvas.width / 2,
                    y: canvas.height / 2,
                    speed: speed,
                    angle: position === 'left' || position === 'right' ? Math.PI : 0,
                    spawnTime: Date.now()
                });
            }

            return deltaTime < 1000 / gameSpeed;
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawPlayer();
            fruits.forEach(fruit => drawFruit(fruit));
        }

        function gameLoop() {
            if (isGameRunning) {
                updatePlayer();
                draw();
                requestAnimationFrame(gameLoop);
            }
        }

        // Event listeners
        startButton.addEventListener('click', () => {
            isGameRunning = true;
            score = 0;
            lastTime = 0;
            document.getElementById('restartButton').style.display = 'none';
            gameLoop();
        });

        restartButton.addEventListener('click', () => {
            isGameRunning = true;
            score = 0;
            lastTime = 0;
            document.getElementById('restartButton').style.display = 'none';
            gameLoop();
        });

        // Game over check
        let gameOver = false;
        setInterval(() => {
            if (!fruits.length && !gameOver) {
                gameOver = true;
                clearInterval();
                alert('Game Over! Your score: ' + score);
                document.getElementById('restartButton').style.display = 'block';
            }
        }, 1000);
    </script>
</body>
</html>
```

