public Object get(Object key) {
    if (cache.containsKey(key)) {
        // It's in the cache, so remove it from its current position and add to the tail
        KeyNode currentNode = (KeyNode) cache.get(key);
        if (currentNode != null) {
            if (currentNode != tail) {
                if (currentNode == head) {
                    head = currentNode.next;
                }
                currentNode.previous.next = currentNode.next;
                if (currentNode.next != null) {
                    currentNode.next.previous = currentNode.previous;
                } else {
                    tail = currentNode.previous;
                }
            }
            // Now, move to the tail
            currentNode.next = tail.next;
            if (tail.next != null) {
                tail.next = currentNode;
                currentNode.previous = tail;
            } else {
                // If there were no nodes after tail, it was the only node, now it's removed
                head = null;
                tail = null;
            }
            cache.remove(key);
            return currentNode.value;
        }
    }
    // If not in cache, add it
    KeyNode newNode = new KeyNode(key, value);
    if (linkedList.size() >= maxSize) {
        // Need to evict
        if (linkedList.isEmpty()) {
            head = newNode;
            tail = newNode;
        } else {
            // Remove the head
            KeyNode toRemove = head;
            head = head.next;
            if (head != null) {
                head.previous = null;
            }
            // Remove from cache
            cache.remove(toRemove.key);
            // Now, add the new node
            newNode.next = head;
            if (head != null) {
                head.previous = newNode;
            }
            tail = newNode;
        }
    } else {
        // Just add to the tail
        newNode.next = tail;
        if (tail != null) {
            tail.next = newNode;
        }
        tail = newNode;
    }
    cache.put(key, newNode);
    return newNode.value;
}

