Here is a C++ program that prints a triangle of stars based on the specified height:

```c++
#include <iostream>

int main() {
    int n;
    std::cout << "Enter the height of the triangle: ";
    std::cin >> n;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < 2 * i - 1; ++j) {
            std::cout << "*";
        }
        std::cout << std::endl;
    }
    return 0;
}
```

