Here's a simple login/signup form with HTML, CSS, and JavaScript:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Login/Signup Form</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Arial', sans-serif;
        }

        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: #f5f5f5;
        }

        .container {
            background: white;
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 0 20px rgba(0,0,0,0.1);
            width: 100%;
            max-width: 500px;
            margin: 20px;
        }

        .form-group {
            margin-bottom: 1rem;
        }

        h2 {
            text-align: center;
            margin-bottom: 2rem;
        }

        .form-title {
            color: #333;
        }

        .switch-form {
            display: block;
            margin-bottom: 1rem;
            text-align: center;
        }

        .input {
            width: 100%;
            padding: 10px;
            border: 1px solid #ddd;
            border-radius: 4px;
            font-size: 16px;
            transition: border-color 0.3s;
        }

        .input:focus {
            outline: none;
            border-color: #007bff;
        }

        .remember {
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
        }

        .remember input {
            width: auto;
            margin-right: 0.5rem;
        }

        button {
            width: 100%;
            padding: 10px;
            background: #007bff;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 16px;
            margin-top: 1rem;
        }

        button:hover {
            background: #0056b3;
        }

        .success-message {
            color: #28a745;
            margin-top: 1rem;
            text-align: center;
            display: none;
        }

        .error {
            color: red;
            margin-top: 0.5rem;
            display: none;
        }
    </style>
</head>
<body>
    <div class="container">
        <h2 class="form-title">Account Access</h2>
        <div class="switch-form">
            <label>Already have an account? 
                <a href="#" onclick="switchForm('login')" style="color: #007bff;">Login</a>
            </label>
        </div>

        <!-- Login Form -->
        <form id="loginForm">
            <div class="form-group">
                <input type="email" placeholder="Email" id="email" required>
            </div>
            <div class="form-group">
                <input type="password" placeholder="Password" id="password" required>
            </div>
            <div class="remember">
                <input type="checkbox" id="remember">
                <label for="remember">Remember me</label>
            </div>
            <button type="submit">Login</button>
        </form>

        <!-- Signup Form -->
        <form id="signupForm">
            <div class="form-group">
                <input type="text" placeholder="Full Name" id="name" required>
            </div>
            <div class="form-group">
                <input type="email" placeholder="Email" id="email" required>
            </div>
            <div class="form-group">
                <input type="password" placeholder="Password" id="password" required>
            </div>
            <button type="submit">Sign Up</button>
        </form>

        <div class="success-message" id="successMessage">Registration successful!</div>
        <div class="error" id="errorMessage"></div>
    </div>

    <script>
        const forms = document.querySelectorAll('form');
        let currentForm = 'login';

        function switchForm(formId) {
            currentForm = formId;
            document.getElementById(currentForm).style.display = 'block';
            document.getElementById('loginForm').style.display = 'none';
            document.getElementById('signupForm').style.display = 'none';

            // Reset form inputs
            document.getElementById('email').value = '';
            document.getElementById('password').value = '';
            document.getElementById('name').value = '';
        }

        function validateForm() {
            let email = document.getElementById('email').value;
            let password = document.getElementById('password').value;
            let name = document.getElementById('name').value;

            let isValid = true;

            if (currentForm === 'login') {
                // Login validation
                if (!email || !password) {
                    document.getElementById('errorMessage').innerHTML = 'Please fill in all fields';
                    isValid = false;
                } else if (password.length < 6) {
                    document.getElementById('errorMessage').innerHTML = 'Password must be at least 6 characters';
                    isValid = false;
                } else {
                    document.getElementById('errorMessage').innerHTML = '';
                }
            } else {
                // Signup validation
                if (!email || !password || !name) {
                    document.getElementById('errorMessage').innerHTML = 'Please fill in all fields';
                    isValid = false;
                } else if (password.length < 6) {
                    document.getElementById('errorMessage').innerHTML = 'Password must be at least 6 characters';
                    isValid = false;
                } else if (!/^\S+@\S+$/.test(email)) {
                    document.getElementById('errorMessage').innerHTML = 'Invalid email format';
                    isValid = false;
                } else {
                    document.getElementById('errorMessage').innerHTML = '';
                }
            }

            return isValid;
        }

        // Prevent default form submission
        forms.forEach(form => {
            form.addEventListener('submit', (e) => {
                e.preventDefault();
                if (validateForm()) {
                    if (currentForm === 'login') {
                        // Login logic here
                        alert('Login successful!');
                        document.getElementById('successMessage').style.display = 'block';
                        document.getElementById('errorMessage').style.display = 'none';
                        switchForm('login');
                    } else {
                        // Signup logic here
                        alert('Registration successful!');
                        document.getElementById('successMessage').style.display = 'block';
                        document.getElementById('errorMessage').style.display = 'none';
                        switchForm('login');
                    }

                    form.reset();
                }
            });
        });
    </script>
</body>
</html>
```

